        this.loyaltyPoints = 0;
        this.titlePurchasedLabel = '';
        this.titleNotPurchasedLabel = '';
        this.subtitleLabel = '';
        this.badgeLabel = '';
        this.orderMetaLabel = '';
        this.ctaLabel = '';
        this.loyaltyLabel = '';
        this.rateLimitMessage = '';
