        await setNestedAsync('ar.trans', 'pages.rating.verified_review.cta', 'تقييم المنتج');
        await setNestedAsync('en.trans', 'pages.rating.verified_review.cta', 'Rate product');
        await setNestedAsync('ar.trans', 'pages.rating.verified_review.loyalty_points', 'اكسب +:points نقطة ولاء بكتابة مراجعة 🏆');
